const tabId = 1962625065;

const cardDetails = await browserjs(tabId, () => {
  // Let's find the container of the two results
  const headers = Array.from(document.querySelectorAll('h2, h3, h4, strong, p, span, div')).filter(el => 
    el.textContent.includes('Demeclocycline Hydrochloride') || el.textContent.includes('Ranitidine Hydrochloride')
  );

  // Find the closest common container or card elements
  const results = [];
  for (const text of ['Demeclocycline', 'Ranitidine']) {
    const el = Array.from(document.querySelectorAll('*')).find(e => e.children.length === 0 && e.textContent.includes(text));
    if (el) {
      let cur = el;
      while (cur && !cur.className.includes('pill') && !cur.className.includes('card') && !cur.className.includes('result') && cur.parentElement && cur.parentElement !== document.body) {
        cur = cur.parentElement;
      }
      results.push({
        text,
        className: cur.className,
        outerHTML: cur.outerHTML.slice(0, 1500),
        innerText: cur.innerText
      });
    }
  }
  return results;
});

console.log(JSON.stringify(cardDetails, null, 2));

